import { create } from "zustand";
import { parseBusServerMessage } from "@spherse/server/contracts";
import type { HostBridge } from "../lib/host-bridge";
import { buildWsUrl } from "../lib/api";

export type BusChannel = "trigger" | "agent" | "fs-watch" | "debug";
export type BusStatus = "idle" | "connecting" | "open" | "closed";
export type BusHandler = (type: string, payload: unknown) => void;

interface BusStore {
  status: BusStatus;
  /** Timestamp of the last successful (re)connection; null before the first connection. */
  resumedAt: number | null;
  init: (bridge: HostBridge) => Promise<void>;
  resumeProbe: () => void;
  addHandler: (projectId: string, channel: BusChannel, handler: BusHandler) => void;
  removeHandler: (projectId: string, channel: BusChannel, handler: BusHandler) => void;
  emitAgentTriggerEvent: (projectId: string, eventName: string, payload?: string) => void;
  teardown: () => void;
}

const RECONNECT_BACKOFFS = [1000, 2000, 5000, 10000, 30000];
const HEARTBEAT_INTERVAL_MS = 30000;
const HEARTBEAT_TIMEOUT_MS = 60000;
const RESUME_PROBE_TIMEOUT_MS = 5000;
const DEBUG_KEY = "__global__::debug";

let ws: WebSocket | null = null;
const handlers = new Map<string, Set<BusHandler>>();
let reconnectTimer: ReturnType<typeof setTimeout> | undefined;
let heartbeatTimer: ReturnType<typeof setInterval> | undefined;
let probeTimer: ReturnType<typeof setTimeout> | undefined;
let lastPongAt = 0;
let reconnectAttempt = 0;
let activeBridge: HostBridge | null = null;

function keyFor(projectId: string, channel: BusChannel): string {
  return `${projectId}::${channel}`;
}

function sendRaw(msg: unknown): void {
  if (ws && ws.readyState === WebSocket.OPEN) {
    try {
      ws.send(JSON.stringify(msg));
    } catch { /* ws closed concurrently */ }
  }
}

function sendSubscribe(projectId: string, channel: BusChannel): void {
  sendRaw({ kind: "subscribe", projectId, channel });
}

function sendUnsubscribe(projectId: string, channel: BusChannel): void {
  sendRaw({ kind: "unsubscribe", projectId, channel });
}

function clearReconnectTimer(): void {
  if (reconnectTimer) {
    clearTimeout(reconnectTimer);
    reconnectTimer = undefined;
  }
}

function clearHeartbeatTimer(): void {
  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
    heartbeatTimer = undefined;
  }
}

function clearProbeTimer(): void {
  if (probeTimer) {
    clearTimeout(probeTimer);
    probeTimer = undefined;
  }
}

function startHeartbeat(): void {
  clearHeartbeatTimer();
  lastPongAt = Date.now();
  heartbeatTimer = setInterval(() => {
    sendRaw({ kind: "ping" });
    if (Date.now() - lastPongAt > HEARTBEAT_TIMEOUT_MS) {
      if (ws) {
        try { ws.close(); } catch { /* already closed */ }
      }
    }
  }, HEARTBEAT_INTERVAL_MS);
}

function replaySubscriptions(): void {
  for (const key of handlers.keys()) {
    const sep = key.indexOf("::");
    const projectId = key.slice(0, sep);
    const channel = key.slice(sep + 2) as BusChannel;
    sendSubscribe(projectId, channel);
  }
}

export const useBusStore = create<BusStore>((set, get) => {
  function scheduleReconnect(): void {
    set({ status: "connecting" });
    clearReconnectTimer();
    const delay = RECONNECT_BACKOFFS[Math.min(reconnectAttempt, RECONNECT_BACKOFFS.length - 1)];
    reconnectAttempt += 1;
    reconnectTimer = setTimeout(() => {
      if (activeBridge) void get().init(activeBridge);
    }, delay);
  }

  return {
    status: "idle",
    resumedAt: null,

    async init(bridge: HostBridge) {
      if (ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING)) {
        return;
      }
      const baseUrl = await bridge.getServerBaseUrl();
      if (!baseUrl) {
        return;
      }
      set({ status: "connecting" });
      activeBridge = bridge;
      const accessToken = (await bridge.getServerAccessToken?.()) ?? null;
      const wsUrl = buildWsUrl(baseUrl, "/ws/bus", accessToken);
      const socket = new WebSocket(wsUrl);
      ws = socket;

      socket.onopen = () => {
        if (ws !== socket) return;
        reconnectAttempt = 0;
        set({ status: "open", resumedAt: Date.now() });
        replaySubscriptions();
        startHeartbeat();
      };

      socket.onmessage = (event) => {
        if (ws !== socket) return;
        let parsed;
        try {
          parsed = parseBusServerMessage(JSON.parse(event.data));
        } catch (err) {
          console.warn("[bus-store] unparseable ws message:", err);
          return;
        }
        if (parsed.channel === "__system__") {
          if (parsed.type === "pong") {
            lastPongAt = Date.now();
            clearProbeTimer();
          } else if (parsed.type === "fs_watch_error") {
            console.debug("[bus-store] fs_watch_error", parsed.payload);
          }
          return;
        }
        const key = parsed.channel === "debug" ? DEBUG_KEY : `${parsed.projectId}::${parsed.channel}`;
        const subs = handlers.get(key);
        if (subs) {
          for (const h of subs) h(parsed.type, parsed.payload);
        }
      };

      socket.onclose = () => {
        if (ws !== socket) return;
        clearHeartbeatTimer();
        scheduleReconnect();
      };

      socket.onerror = () => {
        /* onclose will follow; handled by onclose */
      };
    },

    /**
     * Actively probe the bus connection for liveness (e.g. after the host page
     * resumed from background suspension where iOS silently drops sockets
     * without firing onclose). If the socket is already stale it is closed
     * immediately so the existing reconnect/backoff path takes over; otherwise
     * a ping is sent and a short probe timeout closes the socket if no pong
     * arrives. No-op when the socket is not OPEN (the existing reconnect
     * machinery already owns that case).
     */
    resumeProbe() {
      clearProbeTimer();
      if (!ws || ws.readyState !== WebSocket.OPEN) return;
      if (Date.now() - lastPongAt > HEARTBEAT_TIMEOUT_MS) {
        try { ws.close(); } catch { /* already closed */ }
        return;
      }
      const pongAtStart = lastPongAt;
      sendRaw({ kind: "ping" });
      probeTimer = setTimeout(() => {
        probeTimer = undefined;
        if (ws && ws.readyState === WebSocket.OPEN && lastPongAt === pongAtStart) {
          try { ws.close(); } catch { /* already closed */ }
        }
      }, RESUME_PROBE_TIMEOUT_MS);
    },

    addHandler(projectId, channel, handler) {
      const key = keyFor(projectId, channel);
      let subs = handlers.get(key);
      const wasEmpty = !subs || subs.size === 0;
      if (!subs) {
        subs = new Set();
        handlers.set(key, subs);
      }
      subs.add(handler);
      if (wasEmpty) sendSubscribe(projectId, channel);
    },

    removeHandler(projectId, channel, handler) {
      const key = keyFor(projectId, channel);
      const subs = handlers.get(key);
      if (!subs) return;
      subs.delete(handler);
      if (subs.size === 0) {
        handlers.delete(key);
        sendUnsubscribe(projectId, channel);
      }
    },

    emitAgentTriggerEvent(projectId, eventName, payload) {
      sendRaw({ kind: "emit-trigger-event", projectId, eventName, payload });
    },

    teardown() {
      clearReconnectTimer();
      clearHeartbeatTimer();
      clearProbeTimer();
      if (ws) {
        try { ws.close(); } catch { /* already closed */ }
      }
      ws = null;
      handlers.clear();
      reconnectAttempt = 0;
      lastPongAt = 0;
      activeBridge = null;
      set({ status: "idle", resumedAt: null });
    },
  };
});

import { CHAT_CLOSE_CODES, parseChatServerEvent } from "@spherse/server/contracts";
import type { ApiClient } from "../../../lib/api";
import { buildWsUrl } from "../../../lib/api";
import { parseAgentEvent, type AgentEvent } from "../model/agent-event-parse";
import type { SendableImage } from "../types";
import {
  mergeHistoryMessages,
  parseHistoryMessages,
} from "../model/chat-history";
import {
  reduceSessionEvents,
  type StreamingSessionData,
} from "../model/chat-session-reducer";

const RECONNECT_BACKOFFS = [1000, 2000, 5000, 10000, 30000];
const MAX_RECONNECT_ATTEMPTS = 10;
const RECONCILE_BACKOFFS = [1000, 2000, 5000];
const HEARTBEAT_INTERVAL_MS = 30 * 1000;
const HEARTBEAT_TIMEOUT_MS = 60 * 1000;
const RESUME_PROBE_TIMEOUT_MS = 5 * 1000;
const FATAL_CLOSE_CODES = new Set<number>([
  CHAT_CLOSE_CODES.SESSION_UNRECOVERABLE,
]);

export interface ChatSessionRuntimeState extends StreamingSessionData {
  hasMore: boolean;
  oldestLoadedId: number | null;
  historyStatus: "pending" | "syncing" | "ready";
  connectionStatus: "disconnected" | "connecting" | "open";
  historyError: boolean;
  reconnectFailed: boolean;
}

interface ChatSessionRuntimeParams {
  client: ApiClient;
  baseUrl: string;
  projectId: string;
  agentId: string;
  initialMessage?: string;
  accessToken: string | null;
}

interface ChatSessionRuntimeCallbacks<T extends ChatSessionRuntimeState> {
  getSession(): T | undefined;
  updateSession(updater: (session: T) => T): void;
  enqueueEvent(event: AgentEvent): void;
  applyEvents(events: AgentEvent[]): void;
  flushEvents(): void;
  setStreaming(streaming: boolean): void;
  takeInitialMessage(content: string): boolean;
  shouldReconnect(): boolean;
}

export class ChatSessionRuntime<T extends ChatSessionRuntimeState> {
  private ws: WebSocket | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | undefined;
  private heartbeatTimer: ReturnType<typeof setInterval> | undefined;
  private probeTimer: ReturnType<typeof setTimeout> | undefined;
  private lastHeartbeatTickAt = 0;
  private awaitingPongSince: number | undefined;
  private reconnectAttempt = 0;
  private manuallyClosed = false;
  private params: ChatSessionRuntimeParams | undefined;

  constructor(
    private readonly sessionId: string,
    private readonly callbacks: ChatSessionRuntimeCallbacks<T>,
  ) {}

  connect(params: ChatSessionRuntimeParams): void {
    this.params = params;
    this.manuallyClosed = false;
    this.clearReconnectTimer();
    if (this.ws && this.ws.readyState <= WebSocket.OPEN) return;
    if (this.ws) {
      try {
        this.ws.close();
      } catch (err) {
        console.warn("[chat-session-runtime] failed to close stale WebSocket:", err);
      }
    }

    const ws = new WebSocket(
      buildWsUrl(
        params.baseUrl,
        `/ws/projects/${params.projectId}/chat/${params.agentId}/${this.sessionId}`,
        params.accessToken,
      ),
    );
    this.ws = ws;
    const connectionEvents: AgentEvent[] = [];
    let reconcilingHistory = false;
    let historyWasReady = false;

    const applyConnectionEvents = () => {
      if (connectionEvents.length === 0) return;
      this.callbacks.applyEvents(connectionEvents.splice(0));
    };

    const reconcileHistory = async () => {
      let succeeded = false;
      try {
        for (let attempt = 0; attempt <= RECONCILE_BACKOFFS.length; attempt++) {
          try {
            const result = await params.client.getSessionMessagesPage(
              params.agentId,
              this.sessionId,
              { turns: 10 },
            );
            if (this.ws !== ws || !this.callbacks.getSession()) return;
            const historyMessages = parseHistoryMessages(result.entries);
            this.callbacks.updateSession((session) => {
              const reconciled = {
                ...session,
                messages: mergeHistoryMessages(session.messages, historyMessages),
                hasMore: result.hasMore,
                oldestLoadedId: result.oldestId,
                historyStatus: "ready" as const,
                historyError: false,
              };
              return {
                ...reconciled,
                ...reduceSessionEvents(
                  reconciled,
                  connectionEvents.splice(0),
                  Date.now(),
                ),
              };
            });
            succeeded = true;
            return;
          } catch (err) {
            console.warn(
              "[chat-session-runtime] failed to reconcile session history:",
              err,
            );
            if (this.ws !== ws || !this.callbacks.getSession()) return;
            if (attempt < RECONCILE_BACKOFFS.length) {
              await new Promise((r) => setTimeout(r, RECONCILE_BACKOFFS[attempt]));
              if (this.ws !== ws || !this.callbacks.getSession()) return;
              continue;
            }
            applyConnectionEvents();
            this.callbacks.updateSession((session) => ({
              ...session,
              historyStatus: historyWasReady ? "ready" : "pending",
              historyError: !historyWasReady,
            }));
          }
        }
      } finally {
        reconcilingHistory = false;
        const session = this.callbacks.getSession();
        if (this.ws === ws && session && (succeeded || historyWasReady)) {
          this.callbacks.setStreaming(session.streaming);
        }
      }
    };

    ws.onmessage = (event) => {
      if (this.ws !== ws || !this.callbacks.getSession()) return;
      try {
        const raw = JSON.parse(event.data);
        this.awaitingPongSince = undefined;
        if (raw?.type === "pong") {
          this.clearProbeTimer();
          return;
        }
        const parsed = parseAgentEvent(parseChatServerEvent(raw));
        if (reconcilingHistory) {
          connectionEvents.push(parsed);
        } else {
          this.callbacks.enqueueEvent(parsed);
        }
      } catch (err) {
        console.warn("[chat-session-runtime] unparseable ws event:", err);
      }
    };

    ws.onerror = () => {
      if (this.ws !== ws || !this.callbacks.getSession()) return;
      console.warn("[chat-session-runtime] WebSocket connection error");
      try {
        ws.close();
      } catch (err) {
        console.warn("[chat-session-runtime] failed to close socket on error:", err);
      }
    };

    ws.onclose = (event) => {
      if (this.ws !== ws || !this.callbacks.getSession()) return;
      this.ws = null;
      this.clearHeartbeatTimer();
      if (reconcilingHistory) applyConnectionEvents();
      this.callbacks.flushEvents();
      const fatal = FATAL_CLOSE_CODES.has(event.code);
      this.callbacks.updateSession((session) => ({
        ...session,
        connectionStatus: "disconnected",
        historyStatus:
          session.historyStatus === "syncing"
            ? (historyWasReady ? "ready" : "pending")
            : session.historyStatus,
        messages: fatal
          ? session.messages.map((message) => (
              message._streaming
                ? { ...message, _streaming: false }
                : message
            ))
          : session.messages,
        streaming: fatal ? false : session.streaming,
      }));
      if (fatal) {
        this.callbacks.setStreaming(false);
        this.manuallyClosed = true;
        return;
      }
      if (!this.manuallyClosed && this.callbacks.shouldReconnect()) {
        this.scheduleReconnect();
      }
    };

    ws.onopen = () => {
      if (this.ws !== ws || !this.callbacks.getSession()) return;
      this.startHeartbeat(ws);
      this.reconnectAttempt = 0;
      historyWasReady =
        this.callbacks.getSession()?.historyStatus === "ready";
      reconcilingHistory = true;
      this.callbacks.updateSession((session) => ({
        ...session,
        connectionStatus: "open",
        reconnectFailed: false,
        historyStatus: "syncing",
      }));
      void reconcileHistory();
      if (
        params.initialMessage &&
        this.callbacks.takeInitialMessage(params.initialMessage)
      ) {
        ws.send(JSON.stringify({
          type: "message",
          content: params.initialMessage,
        }));
      }
    };

    this.callbacks.updateSession((session) => ({
      ...session,
      connectionStatus: "connecting",
    }));
  }

  isOpen(): boolean {
    return this.ws?.readyState === WebSocket.OPEN;
  }

  /**
   * Actively probe the socket for liveness after a host resume (e.g. iOS
   * background suspension may leave the socket silently dead). Sends a ping
   * with a short probe timeout; a dead link is closed so the existing
   * reconnect + history-reconcile path takes over. No-op when the socket is
   * not OPEN or a ping is already pending (the heartbeat watchdog owns that
   * case).
   */
  probe(): void {
    this.clearProbeTimer();
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;
    if (this.awaitingPongSince !== undefined) return;
    const ws = this.ws;
    const probeStartedAt = Date.now();
    this.awaitingPongSince = probeStartedAt;
    try {
      ws.send(JSON.stringify({ type: "ping" }));
    } catch (err) {
      console.warn("[chat-session-runtime] probe ping failed:", err);
      return;
    }
    this.probeTimer = setTimeout(() => {
      this.probeTimer = undefined;
      if (this.ws !== ws || this.ws.readyState !== WebSocket.OPEN) return;
      if (this.awaitingPongSince !== undefined && this.awaitingPongSince <= probeStartedAt) {
        try {
          ws.close();
        } catch (err) {
          console.warn("[chat-session-runtime] probe close failed:", err);
        }
      }
    }, RESUME_PROBE_TIMEOUT_MS);
  }

  sendMessage(content: string, image?: SendableImage): boolean {
    if (!this.isOpen()) return false;
    const payload: Record<string, unknown> = { type: "message", content };
    if (image) {
      payload.attachments = [{ type: "image", path: image.path, mimeType: image.mimeType }];
    }
    this.ws?.send(JSON.stringify(payload));
    return true;
  }

  abort(): boolean {
    if (!this.isOpen()) return false;
    this.ws?.send(JSON.stringify({ type: "abort" }));
    return true;
  }

  retry(): boolean {
    if (!this.isOpen()) return false;
    this.ws?.send(JSON.stringify({ type: "retry" }));
    return true;
  }

  respondApproval(requestId: string, approved: boolean): boolean {
    if (!this.isOpen()) return false;
    this.ws?.send(JSON.stringify({
      type: "resolve_control_request",
      requestId,
      kind: "approval",
      approved,
    }));
    return true;
  }

  respondQuestion(requestId: string, answer: string): boolean {
    if (!this.isOpen()) return false;
    this.ws?.send(JSON.stringify({
      type: "resolve_control_request",
      requestId,
      kind: "question",
      answer,
    }));
    return true;
  }

  dispose(): void {
    this.manuallyClosed = true;
    this.clearReconnectTimer();
    this.clearHeartbeatTimer();
    this.clearProbeTimer();
    const ws = this.ws;
    this.ws = null;
    if (ws) {
      try {
        ws.close();
      } catch (err) {
        console.warn("[chat-session-runtime] failed to close WebSocket:", err);
      }
    }
  }

  reconnect(): void {
    if (!this.params) return;
    this.reconnectAttempt = 0;
    this.callbacks.updateSession((session) => ({ ...session, reconnectFailed: false }));
    this.clearReconnectTimer();
    this.connect(this.params);
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer || this.manuallyClosed || !this.params) return;
    if (this.reconnectAttempt >= MAX_RECONNECT_ATTEMPTS) {
      this.callbacks.updateSession((session) => ({ ...session, reconnectFailed: true }));
      return;
    }
    const delay = RECONNECT_BACKOFFS[
      Math.min(this.reconnectAttempt, RECONNECT_BACKOFFS.length - 1)
    ];
    this.reconnectAttempt += 1;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = undefined;
      if (this.params) this.connect(this.params);
    }, delay);
  }

  private startHeartbeat(ws: WebSocket): void {
    this.clearHeartbeatTimer();
    this.lastHeartbeatTickAt = Date.now();
    this.awaitingPongSince = undefined;
    this.heartbeatTimer = setInterval(() => {
      const now = Date.now();
      if (now - this.lastHeartbeatTickAt > HEARTBEAT_TIMEOUT_MS) {
        this.awaitingPongSince = undefined;
      }
      this.lastHeartbeatTickAt = now;
      if (
        this.awaitingPongSince !== undefined &&
        now - this.awaitingPongSince >= HEARTBEAT_TIMEOUT_MS
      ) {
        try {
          ws.close();
        } catch (err) {
          console.warn("[chat-session-runtime] heartbeat close failed:", err);
        }
        return;
      }
      if (ws.readyState === WebSocket.OPEN) {
        try {
          ws.send(JSON.stringify({ type: "ping" }));
          this.awaitingPongSince ??= now;
        } catch (err) {
          console.warn("[chat-session-runtime] heartbeat ping failed:", err);
        }
      }
    }, HEARTBEAT_INTERVAL_MS);
  }

  private clearReconnectTimer(): void {
    if (!this.reconnectTimer) return;
    clearTimeout(this.reconnectTimer);
    this.reconnectTimer = undefined;
  }

  private clearHeartbeatTimer(): void {
    if (!this.heartbeatTimer) return;
    clearInterval(this.heartbeatTimer);
    this.heartbeatTimer = undefined;
  }

  private clearProbeTimer(): void {
    if (!this.probeTimer) return;
    clearTimeout(this.probeTimer);
    this.probeTimer = undefined;
  }
}

import { create, type StoreApi } from "zustand";
import { getLastRoute, setLastRoute } from "../lib/localstorage/last-route";
import type { HostBridge } from "../lib/host-bridge";

export interface ConnectionConfig {
  baseUrl: string;
  accessToken: string | null;
}

export interface ProjectState {
  id: string;
  path: string;
  name: string;
  lastRoute?: string;
  lastOpened: string;
}

interface AppStore {
  connection: ConnectionConfig;
  projects: Map<string, ProjectState>;
  activeProjectId: string | null;
  initializing: boolean;
  restoreProjects: (bridge: HostBridge) => Promise<string | null>;
  refreshProjects: (bridge: HostBridge) => Promise<void>;
  refreshConnection: (bridge: HostBridge) => Promise<void>;
  openProject: (bridge: HostBridge) => Promise<string | null>;
  openSampleProject: (bridge: HostBridge, sampleId: string) => Promise<{ projectId: string | null; error?: string }>;
  closeProject: (bridge: HostBridge, projectId: string) => Promise<string | null>;
  openProjectFolder: (bridge: HostBridge, projectId: string) => Promise<void>;
  setActiveProject: (bridge: HostBridge, projectId: string | null) => Promise<void>;
  setProjectLastRoute: (projectId: string, route: string) => Promise<void>;
}

function findProjectIdByPath(projects: Map<string, ProjectState>, projectPath: string): string | null {
  for (const project of projects.values()) {
    if (project.path === projectPath) return project.id;
  }
  return null;
}

type StoreSetter = StoreApi<AppStore>["setState"];
type StoreGetter = StoreApi<AppStore>["getState"];

async function fetchConnection(bridge: HostBridge): Promise<ConnectionConfig> {
  const baseUrl = await bridge.getServerBaseUrl();
  const accessToken = (await bridge.getServerAccessToken?.()) ?? null;
  return { baseUrl, accessToken };
}

async function registerProject(
  set: StoreSetter,
  get: StoreGetter,
  bridge: HostBridge,
  projectId: string,
  projectPath: string,
): Promise<void> {
  const name = projectPath.split(/[\\/]/).filter(Boolean).pop() || projectPath;
  const projects = new Map(get().projects);
  projects.set(projectId, {
    id: projectId,
    path: projectPath,
    name,
    lastOpened: new Date().toISOString(),
  });
  set({ projects, activeProjectId: projectId });
  await bridge.project?.addOpenProject(projectId, projectPath);
  await bridge.project?.setLastActiveProject(projectId);
}

export const useAppStore = create<AppStore>((set, get) => ({
  connection: { baseUrl: "", accessToken: null },
  projects: new Map(),
  activeProjectId: null,
  initializing: true,

  async restoreProjects(bridge) {
    set({ initializing: true });
    try {
      const connection = await fetchConnection(bridge);
      if (!connection.baseUrl) {
        set({ initializing: false, connection });
        return null;
      }
      const restored = (await bridge.project?.restoreProjects()) ?? [];
      const projects = new Map<string, ProjectState>();

      for (const { id, path, name, lastOpened } of restored) {
        projects.set(id, {
          id,
          path,
          name,
          lastRoute: getLastRoute(id) ?? undefined,
          lastOpened,
        });
      }

      const lastActiveId = (await bridge.project?.getLastActiveProject()) ?? null;
      const fallbackId = projects.keys().next().value ?? null;
      const nextActiveId = lastActiveId && projects.has(lastActiveId) ? lastActiveId : fallbackId;
      set({ connection, projects, activeProjectId: nextActiveId, initializing: false });
      return nextActiveId;
    } catch (err) {
      set({ initializing: false });
      throw err;
    }
  },

  /**
   * Runtime (non-startup) refresh of the project list: merges the latest
   * snapshot into the existing map without flipping `initializing` (no
   * full-screen loading flash) and without disturbing the active project
   * unless it disappeared. Connection config is refreshed as a side effect so
   * baseUrl/token snapshots follow localStorage changes. Throws on fetch
   * failure so callers can surface a toast; state is left untouched then.
   */
  async refreshProjects(bridge: HostBridge) {
    const connection = await fetchConnection(bridge);
    if (!connection.baseUrl) {
      set({ connection });
      return;
    }
    const restored = (await bridge.project?.restoreProjects()) ?? [];
    set((state) => {
      const projects = new Map<string, ProjectState>();
      for (const { id, path, name, lastOpened } of restored) {
        const prev = state.projects.get(id);
        projects.set(id, {
          id,
          path,
          name,
          lastRoute: prev?.lastRoute ?? getLastRoute(id) ?? undefined,
          lastOpened,
        });
      }
      let activeProjectId = state.activeProjectId;
      if (activeProjectId !== null && !projects.has(activeProjectId)) {
        activeProjectId = [...projects.keys()].pop() ?? null;
      }
      return { projects, activeProjectId, connection };
    });
  },

  async refreshConnection(bridge) {
    const connection = await fetchConnection(bridge);
    set((state) => (state.connection === connection ? {} : { connection }));
  },

  async openProject(bridge) {
    const dir = (await bridge.project?.selectDirectory()) ?? null;
    if (!dir) return null;

    const existing = findProjectIdByPath(get().projects, dir);
    if (existing) {
      await get().setActiveProject(bridge, existing);
      return existing;
    }

    const result = await bridge.project?.openProject(dir);
    if (!result) return null;
    const { projectId } = result;
    await registerProject(set, get, bridge, projectId, dir);
    return projectId;
  },

  async openSampleProject(bridge, sampleId) {
    const result = await bridge.project?.openSampleProject({ sampleId });
    if (!result) return { projectId: null };
    if ("error" in result) return { projectId: null, error: result.error };
    await registerProject(set, get, bridge, result.projectId, result.path);
    return { projectId: result.projectId };
  },

  async closeProject(bridge, projectId) {
    const project = get().projects.get(projectId);
    if (!project) return get().activeProjectId;

    await bridge.project?.closeProject(projectId, project.path);

    let nextActiveId: string | null = get().activeProjectId;
    set((state) => {
      const projects = new Map(state.projects);
      projects.delete(projectId);

      if (state.activeProjectId === projectId) {
        const remaining = [...projects.keys()];
        nextActiveId = remaining.length > 0 ? remaining[remaining.length - 1] : null;
      }

      return {
        projects,
        activeProjectId: nextActiveId,
      };
    });

    if (nextActiveId) {
      await bridge.project?.setLastActiveProject(nextActiveId);
    }

    return nextActiveId;
  },

  async openProjectFolder(bridge, projectId) {
    const project = get().projects.get(projectId);
    if (!project) return;
    await bridge.project?.openProjectFolder(project.path);
  },

  async setActiveProject(bridge, projectId) {
    if (!projectId) {
      set({ activeProjectId: null });
      return;
    }
    const project = get().projects.get(projectId);
    set({ activeProjectId: project ? projectId : null });
    if (project) {
      await bridge.project?.setLastActiveProject(projectId);
    }
  },

  async setProjectLastRoute(projectId, route) {
    const project = get().projects.get(projectId);
    if (!project || project.lastRoute === route) return;

    set((state) => {
      const current = state.projects.get(projectId);
      if (!current || current.lastRoute === route) return {};
      const projects = new Map(state.projects);
      projects.set(projectId, { ...current, lastRoute: route });
      return { projects };
    });

    setLastRoute(projectId, route);
  },
}));

const RESUME_RELOAD_THRESHOLD_MS = 30_000;

export function setupWebResumeReload(): () => void {
  let hiddenAt: number | null = null;
  const onVisibility = () => {
    if (document.visibilityState === "hidden") {
      hiddenAt = Date.now();
    } else if (document.visibilityState === "visible" && hiddenAt !== null) {
      if (Date.now() - hiddenAt >= RESUME_RELOAD_THRESHOLD_MS) {
        window.location.reload();
        return;
      }
      hiddenAt = null;
    }
  };
  const onPageShow = (event: PageTransitionEvent) => {
    if (event.persisted) {
      window.location.reload();
    }
  };
  document.addEventListener("visibilitychange", onVisibility);
  window.addEventListener("pageshow", onPageShow);
  return () => {
    document.removeEventListener("visibilitychange", onVisibility);
    window.removeEventListener("pageshow", onPageShow);
  };
}
