  });

  // Connection-recovered compensation: fs-watch events missed while the bus
  // was down are not replayed, so reload the rendered welcome page.
  useReconnectedSync(() => {
    if (!pathRef.current) return;
    setLoadError(false);
    setReloadKey((k) => k + 1);
  });

  useEffect(() => {
    return () => {
      if (reloadTimerRef.current) clearTimeout(reloadTimerRef.current);
    };
  }, []);

  if (path === undefined) return null;
  if (path === null) return <>{fallback}</>;

  if (loadError) {
    return (
      <div className="flex h-full items-center justify-center text-muted-foreground">
        <p>{t("welcome-page.loadFailed")}</p>
      </div>
    );
  }

  const ext = getFileExtension(path);
  const isHtml = HTML_EXTENSIONS.has(ext);
  const previewUrl = client.getPreviewUrl(path);

  if (isHtml) {
    return (
      <iframe
        key={reloadKey}
        src={previewUrl}
        className="flex-1 w-full border-0"
        title="Welcome Page"
        sandbox="allow-scripts allow-same-origin"
        onError={() => setLoadError(true)}
      />
    );
  }

  return (
    <div className="flex h-full items-center justify-center p-8">
      <img
        key={reloadKey}
        src={previewUrl}
        alt="Welcome Page"
        className="max-h-full max-w-full object-contain"
        onError={() => setLoadError(true)}
      />
    </div>
  );
}

