    const socket = mock.instances[mock.instances.length - 1];
    socket.readyState = OPEN;
    socket.onopen?.({} as Event);
    await vi.advanceTimersByTimeAsync(0);
    return socket;
  }

  it("attach opens a websocket to the chat endpoint", async () => {
